describe("comments", () => {
  it("requests top-level comments chronologically for a post", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(ok({ data: [] }))
    await createPagesClient({ accessToken: "t", fetchImpl }).comments.forPost("p1")

    const url = new URL(fetchImpl.mock.calls[0]![0] as string)
    expect(url.pathname).toBe(`/${GRAPH_API_VERSION}/p1/comments`)
    expect(url.searchParams.get("filter")).toBe("toplevel")
    expect(url.searchParams.get("order")).toBe("chronological")
  })

  it("reads replies from the comment's own comments edge", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(ok({ data: [{ id: "c2" }] }))
    const { items } = await createPagesClient({ accessToken: "t", fetchImpl }).comments.replies(
      "c1",
    )

    expect(new URL(fetchImpl.mock.calls[0]![0] as string).pathname).toBe(
      `/${GRAPH_API_VERSION}/c1/comments`,
    )
    expect(items).toEqual([{ id: "c2" }])
  })

  it("posts a reply and returns the created id", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(ok({ id: "c1_r1" }))
    const created = await createPagesClient({ accessToken: "t", fetchImpl }).comments.reply(
      "c1",
      "Thanks for asking!",
    )

    const [url, init] = fetchImpl.mock.calls[0]! as [string, RequestInit]
    expect(init.method).toBe("POST")
    expect(new URL(url).pathname).toBe(`/${GRAPH_API_VERSION}/c1/comments`)
    expect(created).toEqual({ id: "c1_r1" })
  })

  it("never puts reply text in the query string", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(ok({ id: "c1_r1" }))
    await createPagesClient({ accessToken: "t", fetchImpl }).comments.reply("c1", "secret text")

    expect(fetchImpl.mock.calls[0]![0] as string).not.toContain("secret")
  })

  it("hides and unhides through one endpoint with a boolean", async () => {
    // mockImplementation (not mockResolvedValue) so each call gets a fresh
    // Response: a Response body can only be read once, and setHidden is
    // called twice here.
    const fetchImpl = vi.fn().mockImplementation(async () => ok({ success: true }))
    const client = createPagesClient({ accessToken: "t", fetchImpl })

    await client.comments.setHidden("c1", true)
    await client.comments.setHidden("c1", false)

    for (const call of fetchImpl.mock.calls) {
      const [url, init] = call as [string, RequestInit]
      expect(init.method).toBe("POST")
      expect(new URL(url).pathname).toBe(`/${GRAPH_API_VERSION}/c1`)
    }
    expect(String((fetchImpl.mock.calls[0]![1] as RequestInit).body)).toContain("is_hidden=true")
    expect(String((fetchImpl.mock.calls[1]![1] as RequestInit).body)).toContain("is_hidden=false")
  })
})

